contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint balAfterAdd = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalAfterAdd = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfterWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalAfterWithdraw = address(c).balance;

        assert(
            !reverted &&
            balAfterAdd == balBefore + amount &&
            contractBalAfterAdd == contractBalBefore + amount &&
            balAfterWithdraw == 0 &&
            contractBalAfterWithdraw == contractBalBefore
        );
    }

    receive() external payable {}
}

