pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 balBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 balAfterAdd;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfterAdd = __r; } catch { return; }
        uint contractBalAfterAdd = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfterWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfterWithdraw = __r; } catch { return; }
        uint contractBalAfterWithdraw = address(c).balance;
        assertTrue(!reverted &&
            balAfterAdd == balBefore + amount &&
            contractBalAfterAdd == contractBalBefore + amount &&
            balAfterWithdraw == 0 &&
            contractBalAfterWithdraw == contractBalBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
